WITH filtered AS (SELECT id, session_id, event_type, page, event_time, duration_sec, TRIM(page) AS clean_page, COALESCE(page, 'OTHER') AS page_filled FROM web_events WHERE page IS NOT NULL AND page IS DISTINCT FROM '/checkout') SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY session_id, event_type ORDER BY event_time DESC, id) AS latest_rank FROM filtered) t WHERE latest_rank = 1;
